package com.bananalab.lite;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public class Stage38ModelsCheck{
 public static void main(String[] args)throws Exception{String r=args[0];PixelGenerator p=new PixelGenerator(new FileInputStream(r+"/assets/custom23/custom23.bin"));float max=0;try(DataInputStream in=new DataInputStream(new FileInputStream(r+"/model-source/custom23-reference.bin"))){int cases=in.readInt(),n=in.readInt();for(int row=0;row<cases;row++){float[] x=new float[n];for(int i=0;i<n;i++)x[i]=in.readFloat();float[] y=p.forward(x);for(int i=0;i<4;i++)max=Math.max(max,Math.abs(y[i]-in.readFloat()));}}if(max>.0005)throw new AssertionError("mask parity "+max);System.out.println("CUSTOM_MASK_PARITY "+max);String[] labels=new String(Files.readAllBytes(Paths.get(r+"/assets/context1/labels.txt")),"UTF-8").trim().split("\\n");ContextEncoder model=new ContextEncoder(new FileInputStream(r+"/assets/context1/context1.bin"),labels);max=0;try(DataInputStream in=new DataInputStream(new FileInputStream(r+"/model-source/context1-reference.bin"))){int cases=in.readInt(),n=in.readInt();for(int row=0;row<cases;row++){float[] x=new float[n];for(int i=0;i<n;i++)x[i]=in.readFloat();float[] y=model.forward(x);for(int i=0;i<y.length;i++)max=Math.max(max,Math.abs(y[i]-in.readFloat()));}}if(max>.0005)throw new AssertionError("context parity "+max);JSONObject card=new JSONObject(new String(Files.readAllBytes(Paths.get(r+"/assets/context1/model-card.json")),"UTF-8"));JSONArray rows=card.getJSONArray("heldout");int same=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String prediction=model.label(row.getString("q")),expected=row.getDouble("confidence")>=.85?row.getString("actual"):"unknown";if(prediction.equals(expected))same++;}if(same!=rows.length())throw new AssertionError("runtime intent gate differs "+same);System.out.println("CONTEXT_PARITY "+max+"; own held-out confidence routing "+same+"/"+rows.length());}
}
